/* Original beginner bridge for the first seven lessons. Self-checks are objective mini-questions, not AI assessment. */
(()=>{'use strict';
const lessons=[
{
 qa:{goal:'Понять, что вообще делает тестировщик.',explain:'Программа получает действие и выдаёт результат. Требование говорит, что должно произойти. Тестирование сравнивает результат с требованием. QA шире: команда предупреждает проблемы ещё до выпуска продукта.',steps:['Придумай правило: «Удаление карты требует подтверждения».','Запиши начальное условие: карта уже создана.','Запиши действие: открыть карту, нажать «Удалить», подтвердить.','Запиши ожидаемый результат: карта исчезает.','Отмена — отдельный тест: после отмены карта остаётся.'],practice:'Составь три независимых тест-кейса: подтверждение удаления, отмена, сохранение результата после обновления. Для каждого напиши «Условие / Шаги / Ожидаю».',question:'Где написано, как приложение ДОЛЖНО работать?',choices:['В требовании','В случайном мнении пользователя','В названии кнопки'],correct:0,why:'Требование описывает нужное поведение. Если оно неясно, сначала задаём вопрос.'},
 python:{goal:'Увидеть, как работает первая программа.',explain:'Python выполняет команды сверху вниз. print() выводит информацию. Имя переменной позволяет обращаться к сохранённому значению. input() получает текст. if выбирает действие, если условие истинно. Не нужно запоминать всё сразу: сначала освой print().',steps:['Набери print("Привет!") и запусти: появится слово «Привет!».','Добавь name = "Мир" и print(name): вывод берётся из переменной.','Попробуй name = input("Имя: ") и впиши тестовое имя в поле ввода консоли.','Только затем разбери if: сравнение == даёт True или False; тело условия пишут с отступом.'],practice:'Запусти print("Мой первый код") без ошибок. Потом измени строку и объясни, откуда взялся вывод. Вернись к большому заданию урока постепенно.',question:'Что делает print("Привет")?',choices:['Выводит текст','Запрашивает пароль','Создаёт сайт'],correct:0,why:'print() показывает значение в области вывода. input() — другая команда: она получает данные.'},
 english:{goal:'Начать с букв и простого приветствия.',explain:'Английский изучаем от звуков к словам, от слов к коротким фразам. Буква и звук не всегда совпадают. Сегодня знакомство с буквами A–F и словами hello (привет), yes (да), no (нет).',steps:['Прочитай буквы A, B, C, D, E, F. Не пытайся пока выучить весь алфавит за один раз.','Послушай слово дня кнопкой ниже, если браузер поддерживает озвучивание.','Скажи вслух: Hello! I am ... (Привет! Я ...).','Закрой перевод карточки, попробуй вспомнить и открой для проверки.'],practice:'Напиши Hello! I am Alex. (подставь любое учебное имя), затем переведи слово дня в поле задания.',question:'Что означает Hello?',choices:['Привет','До свидания','Проверка'],correct:0,why:'Hello — приветствие. I am ... — «Я ...».'}
},
{
 qa:{goal:'Научиться писать проверяемые требования.',explain:'«Кнопка должна хорошо работать» проверить невозможно: непонятно, что считать правильным. «После сохранения карточка остаётся в списке после перезагрузки страницы» можно проверить по факту.',steps:['Выбери одну функцию: добавление карты.','Опиши действие пользователя без слов «хорошо» и «удобно».','Сформулируй наблюдаемый результат.','Запиши критерий приёмки: в каких условиях функция считается готовой.'],practice:'Составь пять требований к добавлению карты. Отметь, по каким двум легко составить тест.',question:'Какое утверждение можно проверить?',choices:['Сайт красивый','После сохранения карточка видна в списке','Приложение великолепно'],correct:1,why:'Во втором утверждении есть конкретный наблюдаемый результат.'},
 python:{goal:'Разобраться со строками и текстом.',explain:'Строка — текст, заключённый в кавычки. Переменная сохраняет строку. f-строка позволяет вставлять переменную в текст без сложного сложения строк.',steps:['Выполни name = "Alex" и print(name).','Затем print(f"Привет, {name}!").','Измени значение name и сравни вывод.','Попробуй input(): это всегда строка, даже когда введены цифры.'],practice:'Создай переменные name и language; выведи их одной f-строкой. Объясни, зачем нужны фигурные скобки.',question:'Какой тип возвращает input()?',choices:['Всегда str (строку)','Всегда int','Всегда bool'],correct:0,why:'Если требуется число, строку нужно дополнительно преобразовать — например, через int().'},
 english:{goal:'Продолжить алфавит и познакомиться.',explain:'Сегодня буквы G–L. В коротком диалоге Hello! — приветствие, My name is ... — «Меня зовут ...». Не обязательно сразу говорить быстро: важнее понимать каждую часть.',steps:['Повтори A–F и прочитай G, H, I, J, K, L.','Произнеси Hello! и My name is Alex.','Прочитай пример: What is your name? — Как тебя зовут?','Попробуй ответить: My name is ... .'],practice:'Составь две строки диалога знакомства и переведи слово дня.',question:'Как сказать «Меня зовут Алекс»?',choices:['My name is Alex.','I name Alex?','Name my Alex.'],correct:0,why:'Устойчивое выражение для знакомства — My name is ... .'}
},
{
 qa:{goal:'Отличать правильные и неправильные входные данные.',explain:'Позитивный тест использует данные, соответствующие требованию. Негативный использует недопустимые данные и проверяет, что приложение понятно их обрабатывает. Неверный ввод сам по себе ещё не баг.',steps:['Выбери правило: поле обязательно для заполнения.','Позитивная проверка: введи допустимое значение.','Негативная: оставь поле пустым.','Для обоих запиши ожидаемый результат по требованию.'],practice:'Придумай три допустимых и три недопустимых значения email; не утверждай, что твой список охватывает все возможные форматы.',question:'Что проверяет негативный тест?',choices:['Только внешний вид','Поведение на недопустимых данных','Любой случайный ввод'],correct:1,why:'Отрицательный сценарий должен иметь ожидаемый результат, например понятное сообщение об ошибке.'},
 python:{goal:'Не путать присваивание и сравнение.',explain:'Один знак = сохраняет значение. Два знака == сравнивают значения. Выражение сравнения даёт True либо False.',steps:['Запусти x = 5, затем print(x).','Запусти print(x == 5): это True.','Измени x на 8 и снова проверь сравнение.','Разбери != (не равно), > и <.' ],practice:'Введи два учебных числа через int(input()), сравни их и объясни вывод.',question:'Что означает x == 5?',choices:['Сравнить x с 5','Присвоить x число 5','Напечатать x'],correct:0,why:'Оператор == сравнивает, а = присваивает.'},
 english:{goal:'Собрать первое простое предложение.',explain:'Буквы M–R. Фраза I am a student. означает «Я ученик/студент». В английском обычно нужен глагол am между I и описанием. Сравни: I am ready. — «Я готов».',steps:['Повтори A–L, затем прочитай M, N, O, P, Q, R.','Произнеси: I am ready.','Замени ready на happy: I am happy.','Скажи одну фразу о себе, не спеша.'],practice:'Напиши I am ready. и I am a student. с переводами и выполни словарное упражнение.',question:'Как правильно «Я готов»?',choices:['I ready','I am ready','Am I ready I'],correct:1,why:'После I в утвердительной фразе нужен am.'}
},
{
 qa:{goal:'Находить ошибки на границах допустимого.',explain:'Если длина имени от 3 до 10 символов, важны 2, 3, 10 и 11. Рядом с границей поведение меняется. Просто случайные длинные строки такую проверку не заменят.',steps:['Запиши точные ограничения поля.','Выбери значение чуть меньше нижней границы.','Выбери обе границы.','Выбери значение чуть больше верхней границы.','Запиши ожидаемый результат для каждой проверки.'],practice:'Для правила «длина от 3 до 10» составь тесты для значений 2, 3, 10, 11.',question:'Какая группа проверяет границы 3–10?',choices:['4, 5, 6','2, 3, 10, 11','20, 30, 40'],correct:1,why:'Проверяем непосредственно соседние и граничные значения.'},
 python:{goal:'Преобразовать строку в число.',explain:'input() возвращает текст. int() пытается сделать целое число. Например int("18") превращается в 18, а int("кот") вызовет ValueError. Позже мы научимся аккуратно обрабатывать ошибки ввода.',steps:['Запусти print(type(input("Возраст: "))) с тестовым вводом 18.','Сравни с print(type(int("18"))).','Напиши age = int(input("Возраст: ")).','Проверь условия для 17, 18, 19.'],practice:'Объясни, почему текст "18" и число 18 ведут себя по-разному при сравнении с числом.',question:'Что делает int("18")?',choices:['Создаёт целое число 18','Печатает текст «18»','Создаёт список'],correct:0,why:'int() преобразует допустимую числовую строку в int.'},
 english:{goal:'Закончить первое знакомство с буквами.',explain:'Оставшиеся буквы S–Z: S, T, U, V, W, X, Y, Z. Порядок букв и их английские названия полезны при чтении адресов и написании слов по буквам.',steps:['Повтори A–R и прочитай S–Z.','Напиши своё учебное имя латиницей.','Попробуй назвать его буквы по одной.','Повтори: Hello! My name is ... .'],practice:'Напиши буквы английского алфавита A–Z и составь простое приветствие.',question:'Какая буква идёт после W?',choices:['Y','X','V'],correct:1,why:'Конец алфавита: W, X, Y, Z.'}
},
{
 qa:{goal:'Различать чек-лист и подробный тест-кейс.',explain:'Чек-лист — компактное напоминание, что проверить. Тест-кейс задаёт конкретные условия, шаги и ожидания. Оба полезны, когда их формат соответствует задаче.',steps:['Запиши пять коротких пунктов проверки формы.','Выбери один пункт.','Добавь необходимые условия и конкретные шаги.','Добавь ожидаемый результат и сравни с требованием.'],practice:'Составь десять пунктов чек-листа, затем преврати один из них в тест-кейс.',question:'Где обычно подробно записаны шаги и ожидание?',choices:['В тест-кейсе','Только в названии проекта','В случайном комментарии'],correct:0,why:'Тест-кейс нужен в том числе для повторения проверки другим человеком.'},
 python:{goal:'Понять порядок if, elif и else.',explain:'if проверяет первое условие. Если оно ложно, elif проверяет следующее. else — оставшийся случай. После if и elif ставят двоеточие; вложенный код должен быть с отступом.',steps:['Проверь программу с числом score = 30.','Замени score на 60, затем на 90.','Объясни, почему срабатывает только одна ветка.','Измени сообщение в ветке else.'],practice:'Напиши программу с тремя результатами в зависимости от учебного балла и проверь её на всех трёх случаях.',question:'Когда запускается else?',choices:['Если предыдущие условия не выполнились','Всегда первым','Одновременно с каждым if'],correct:0,why:'else обрабатывает случай, который не подошёл ни под одно предыдущее условие.'},
 english:{goal:'Научиться говорить «да» и «нет» в диалоге.',explain:'Yes — да, no — нет. Вопрос Are you ready? означает «Ты готов?». Краткие ответы: Yes, I am. / No, I am not. Начни с понимания смысла, затем произнеси фразы.',steps:['Прочитай вопрос Are you ready?','Ответь Yes, I am.','Ответь No, I am not.','Произнеси обе пары вопрос–ответ.'],practice:'Напиши мини-диалог из вопроса и двух возможных ответов. Повтори слова предыдущих дней.',question:'Что ответить на Are you ready? утвердительно?',choices:['Yes, I am.','Yes, I not.','No, I am.'],correct:0,why:'Yes, I am. — правильный краткий утвердительный ответ.'}
},
{
 qa:{goal:'Научиться описывать реальный дефект.',explain:'Баг-репорт — инструкция для воспроизведения наблюдённого поведения. Не заполняй фактический результат выдумкой. Если баг не найден, пометь отчёт как учебный пример.',steps:['Укажи название и окружение: устройство, браузер, версия.','Запиши предусловие и последовательные шаги.','Укажи ожидаемое поведение на основании требования.','Укажи только действительно увиденное фактическое поведение.'],practice:'На своём учебном интерфейсе исследуй сохранение записи. Если ошибки нет, составь явно учебный баг-репорт как гипотезу.',question:'Когда можно заполнить фактический результат?',choices:['До запуска, наугад','После воспроизведения и наблюдения','Вместо ожидаемого результата'],correct:1,why:'Фактический результат — наблюдение, а не догадка.'},
 python:{goal:'Выводить понятный отчёт текстом.',explain:'f-строка подставляет переменные. Символы \\n внутри строки обозначают переход на новую строку. Сначала можно выводить каждый пункт отдельным print() — важен смысл, а не сложная запись.',steps:['Сохрани feature = "Сохранение".','Сохрани expected = "Запись осталась".','Выведи оба значения двумя print().','Объедини текст через f-строку и добавь фактический результат.'],practice:'Сделай текстовый отчёт из названия функции, ожидания и факта. Объясни, какая строка откуда берётся.',question:'Зачем нужен префикс f в f"Результат: {value}"?',choices:['Чтобы подставить value в строку','Чтобы удалить файл','Чтобы выполнить цикл'],correct:0,why:'В f-строке выражения в фигурных скобках вычисляются и подставляются в текст.'},
 english:{goal:'Повторить базовое знакомство без подсказок.',explain:'Сегодня вспоминаем алфавит, Hello, My name is ..., I am ..., Yes, I am. / No, I am not. Повторение важнее количества новых слов.',steps:['Произнеси буквы A–Z, отмечая, какие ещё забываешь.','Закрой перевод карточек и вспомни значения.','Напиши три простые фразы о себе.','Прочитай их вслух; сравни с образцами.'],practice:'Составь четыре реплики знакомства: приветствие, вопрос об имени, ответ, прощание Goodbye. Добавь перевод.',question:'Как сказать «Меня зовут Сэм»?',choices:['My name is Sam.','My is name Sam.','I name is Sam.'],correct:0,why:'Устойчивый порядок: My name is + имя.'}
},
{
 qa:{goal:'Проверить, что базовые понятия освоены.',explain:'Контрольная неделя — самостоятельная работа. Не нужно закрывать урок только ради последовательности: если тест-кейс пока непонятен, вернись к соответствующему дню.',steps:['Без подсказок объясни «требование», «тест-кейс», «чек-лист», «баг-репорт».','Напиши проверяемое требование.','Сделай позитивный, негативный и граничный тесты.','Оформи один подробный тест-кейс.'],practice:'Создай 10 проверок собственного учебного проекта и тест-кейс. Проверь, понимаешь ли ожидаемый результат каждого.',question:'Как узнать, что проверка сработала?',choices:['Сравнить реальный результат с ожидаемым','Посчитать количество нажатий','Посмотреть только на цвет кнопки'],correct:0,why:'Проверяем наблюдаемый результат относительно требования.'},
 python:{goal:'Написать первую мини-программу самостоятельно.',explain:'Собери пройденное: переменная, input(), int(), сравнение и if/elif/else. Начинай с маленькой работающей части. Затем добавляй по одной конструкции и запускай снова.',steps:['Выведи приветствие print().','Запроси учебный балл через input() и преобразуй через int().','Добавь три ветки для разных интервалов баллов.','Запусти программу с тремя значениями и сравни ожидания.'],practice:'Напиши мини-программу с тремя исходами, объясни её код и проверь минимум три значения. Не копируй решение без понимания.',question:'Что проверить после изменения кода?',choices:['Запустить и сравнить вывод с ожиданием','Сразу считать программу готовой','Удалить все предыдущие версии'],correct:0,why:'Тестовые запуски помогают заметить ошибки, но дополнительно нужна проверка по условиям задания.'},
 english:{goal:'Пройти первую небольшую проверку разговорных основ.',explain:'К концу недели цель скромная и проверяемая: узнать буквы, понять простое приветствие, представить себя и ответить на базовый вопрос. Это начало обучения английскому, не готовый уровень владения языком.',steps:['Без подсказок напиши алфавит.','Скажи Hello! My name is ... .','Ответь на Are you ready?','Переведи пять карточек и повтори забытые.'],practice:'Составь короткий диалог знакомства на 4–6 реплик и переведи его на русский.',question:'Как корректно ответить «Нет, я не готов»?',choices:['No, I am not ready.','Yes, I not.','No, ready I am.'],correct:0,why:'Отрицание после am: I am not ready.'}
}
];
function init(){
 const topic=document.getElementById('topic'),answer=document.getElementById('answerLabel'),select=document.getElementById('lessonSelect');
 if(!topic||!answer||!select)return;
 const panel=document.createElement('section');panel.id='foundationPanel';panel.className='foundation';panel.setAttribute('aria-label','Пошаговый урок для новичка');answer.before(panel);
 const make=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;};
 const active=()=>['qa','python','english'].find(b=>document.getElementById(`tab${b==='qa'?'Qa':b==='python'?'Python':'English'}`)?.getAttribute('aria-pressed')==='true')||'qa';
 function render(){
  const n=Number(select.value)||1,data=lessons[n-1]?.[active()];
  panel.hidden=!data;if(!data)return;
  panel.replaceChildren();panel.append(make('span',`СТАРТ С НУЛЯ · УРОК ${n}/7`,'eyebrow'),make('h4',data.goal),make('p',data.explain,'foundation-intro'));
  panel.append(make('span','РАЗБЕРИ ПО ПОРЯДКУ','eyebrow'));
  const steps=make('ol','');for(const step of data.steps)steps.append(make('li',step));panel.append(steps);
  const task=make('div','','foundation-task');task.append(make('strong','Твоя практика'),make('p',data.practice));panel.append(task);
  if(active()==='english'){
   const word=window.AcademyGuide?.english(n)?.main?.word;
   if(word&&'speechSynthesis' in window&&typeof window.SpeechSynthesisUtterance==='function'){
    const speak=make('button',`▶ Послушать «${word}»`,'foundation-speak');speak.type='button';speak.addEventListener('click',()=>{
      try{window.speechSynthesis.cancel();const phrase=new SpeechSynthesisUtterance(word);phrase.lang='en-US';phrase.rate=.8;window.speechSynthesis.speak(phrase);}catch{const note=make('p','Озвучивание недоступно в этом браузере. Продолжи с карточками и чтением.');speak.after(note);speak.disabled=true;}
    });panel.append(speak,make('p','Озвучивание зависит от голосов устройства и не оценивает твоё произношение.','foundation-note'));
   }
  }
  const check=make('div','','foundation-check');check.append(make('span','КОРОТКАЯ ПРОВЕРКА ПОНИМАНИЯ','eyebrow'),make('h5',data.question));
  const choices=make('div','','foundation-choices'),feedback=make('p','','foundation-feedback');feedback.setAttribute('role','status');
  data.choices.forEach((choice,index)=>{const button=make('button',choice,'foundation-option');button.type='button';button.addEventListener('click',()=>{
    for(const other of choices.querySelectorAll('button')){other.classList.remove('is-right','is-wrong');other.setAttribute('aria-pressed','false');}
    button.setAttribute('aria-pressed','true');button.classList.add(index===data.correct?'is-right':'is-wrong');feedback.textContent=(index===data.correct?'Верно. ':'Ещё раз подумай. ')+data.why;
   });choices.append(button);});check.append(choices,feedback);panel.append(check);
  const reminder=make('p','Это дополнительное упражнение для понимания. Галочка ставится по правилам основного урока; один правильный ответ не доказывает освоение всей темы.','foundation-note');panel.append(reminder);
 }
 new MutationObserver(render).observe(topic,{childList:true,characterData:true,subtree:true});render();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
